# A resposta do técnico a uma história da mídia sobre um jogador (Media::apply_player_story_response 0x741020,
# media.cpp, 3888 bytes, 1273 instruções; 372 chamadas na carreira ENG até 2002-06-01). Partida em quatro pedaços por
# história: 0x25 (rival de posição), 0x1f (interesse de outro clube), 0x20 (desabafo [inferência]) e as outras; o
# comparador diz o pedaço. Igual no cm0102-1080.exe (os 0xf30 bytes conferidos). Convenções conferidas na desmontagem:
# - a rotina: thiscall(mídia, jogador, clube, história, resposta), ret 0x10; a história comparada como palavra (cmp di),
#   a resposta como byte (movsx), mas as duas passam inteiras (o dword) adiante para 0x738340/0x7386f0/0x736c00;
# - 0x4cf5a0: mov ecx, [0xae1050]; push jogador -> ret 4 (duas vezes na resposta 2 da 0x25); 0x53b900 cdecl (clube),
#   chamada duas vezes; 0x4a2e10: push 3; push clube; mov ecx, estatísticas -> ret 8, st0 guardado como float;
# - cdecl: 0x547790/0x5477d0 (jogador, clube), 0x547810/0x547840 (jogador, outro), 0x544710 (pessoa, delta, 1),
#   0x547af0 (jogador, técnico, 1), 0x547c50 (jogador, técnico), 0x90cfc0 (n) (o "push 1" antes do sorteio de 8 e de
#   5 no laço da 0x1f é o terceiro argumento da 0x544710 adiantado);
# - thiscall no contrato: 0x866f60 (ret 0), 0x8676f0 (ret 0), 0x8676d0 (0x800, ret 4), 0x867560 (0x800, ret 4),
#   0x867700 (marcas, 0, ret 8);
# - mov ecx, mídia: 0x738340 (clube, jogador, história, alvo, resposta) ret 0x14; 0x7386f0 (+ 0) ret 0x18; 0x736c00
#   (clube, história, marcas, peso f32, resposta, 0, jogador) ret 0x1c; 0x72bbf0 (jogador, clube, 0x25) stdcall ret 0xc;
# - 0x56a100: mov ecx, [0xae2a30]; (jogador, clube, 4, 0/1) ret 0x10;
# - x87: peso do presidente (ambição − 10) × 0,05 + 1 (0,5 sem presidente) em qword local; _ftol de peso × 1000 − 2000,
#   peso × −1000 − 2000 e peso × 3000.
# A 0x73e870 (apply_team_story_response, 10160 bytes) ficou de fora: ver PRONTO.txt.
